import { ObjectSchema } from "./utils/plugin-options-schema-joi-type"

interface ITestPluginOptionsSchemaReturnType {
  isValid: boolean
  errors: Array<string>
}

/**
 * Validates a (partial) set of plugin options against a plugin's Joi schema.
 *
 * Unlike a full validation, only the keys present in `pluginOptions` are
 * checked. This lets plugin authors unit test their schema against a subset of
 * options without triggering "is required" errors for keys they left out.
 */
export async function testPluginOptionsSchema(
  pluginSchemaFunction: ({ Joi }: { Joi: any }) => ObjectSchema,
  pluginOptions: Record<string, unknown>
): Promise<ITestPluginOptionsSchemaReturnType> {
  const pluginSchema = pluginSchemaFunction({ Joi })

  const errors: Array<string> = []

  for (const key of Object.keys(pluginOptions)) {
    let subSchema
    try {
      subSchema = pluginSchema.extract(key)
    } catch (e) {
      // The key isn't part of the schema, so there's nothing to validate it
      // against. Skip it rather than crashing.
      continue
    }

    const { error } = subSchema
      .label(key)
      .validate(pluginOptions[key], { abortEarly: false })

    if (!error) {
      continue
    }

    // Array item errors reference the failing index (e.g. `"[0]"`) rather than
    // the field name, so prefix them once with the field name and join them
    // into a single message. Scalar errors already include the field name.
    const isArrayItemError = error.details.some(detail => detail.path.length > 0)
    const message = error.details.map(detail => detail.message).join(`. `)

    errors.push(isArrayItemError ? `"${key}" ${message}` : message)
  }

  return {
    isValid: errors.length === 0,
    errors,
  }
}
